package io.github.easychat.chat;

import java.util.regex.Pattern;

/** Removes subtitle presentation metadata sometimes generated by OPUS. */
public final class TranslationOutput {
    private static final Pattern ASS_OVERRIDE = Pattern.compile("\\{\\\\[^{}]*\\}");
    private static final Pattern ASS_INCOMPLETE = Pattern.compile("\\{\\\\[^{}]*$");
    private static final Pattern CONTENT = Pattern.compile("[\\p{L}\\p{N}]");
    private TranslationOutput() { }
    public static String clean(String text) {
        if (text == null) return "";
        String plain = ASS_OVERRIDE.matcher(text).replaceAll("");
        plain = ASS_INCOMPLETE.matcher(plain).replaceAll("");
        return plain.replaceAll("\\\\[Nnh]", " ").replaceAll("§.", "")
                .replaceAll("[\\p{Cntrl}\\p{Cf}]", " ").replaceAll("\\s+", " ").trim();
    }
    public static boolean hasContent(String text) {
        return text != null && CONTENT.matcher(text).find();
    }
}
